exec('import csv,os,yfinance as yf\nT={x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()}; rows=[r for r in csv.DictReader(open("signals_history.csv",encoding="utf-8")) if r["ticker"] in T]; latest={}\nfor r in rows:\n if r["ticker"] not in latest or r["date"]>latest[r["ticker"]]["date"]: latest[r["ticker"]]=r\ncandidates=[r for r in latest.values() if r["signal"]=="ACHAT"]; decisions=[]; print("===== CONFIRMATION INTRADAY - SIMULATION =====")\nif not candidates: print("Aucun candidat ACHAT disponible.")\nfor r in candidates:\n t=r["ticker"]; signal_date=r["date"]; signal_price=float(r["price"])\n try:\n  d=yf.download(t,period="5d",interval="5m",progress=False,auto_adjust=True,prepost=False)\n  if d.empty: print("\\n"+t+" | AUCUNE DONNEE"); continue\n  if hasattr(d.columns,"levels"): d.columns=d.columns.get_level_values(0)\n  sessions=sorted({x.strftime("%Y-%m-%d") for x in d.index if x.strftime("%Y-%m-%d")>signal_date})\n  if not sessions: print("\\n"+t+" | EN ATTENTE DU JOUR J"); continue\n  session=sessions[0]; s=d[d.index.strftime("%Y-%m-%d")==session].copy()\n  if len(s)<4: print("\\n"+t+" | EN ATTENTE DES 4 BOUGIES | Disponibles : "+str(len(s))); continue\n  opening=float(s["Open"].iloc[0]); gap=(opening/signal_price-1)*100; first4=s.iloc[:4]; or_high=float(first4["High"].max()); or_low=float(first4["Low"].min()); close4=float(first4["Close"].iloc[-1]); red4=int((first4["Close"]<first4["Open"]).sum()); vv=first4["Volume"][first4["Volume"]>0]; vol4=float(vv.mean()) if len(vv)>0 else 0; decision="EN ATTENTE"; next_state="PENDING"; reason="Prix dans Opening Range"; dt=""; op=""; hi=""; lo=""; cl=""; vol=""; vwap_value=""\n  if gap<=-3: decision="SETUP INITIAL INVALIDE"; next_state="SURVEILLANCE CATALYSEUR"; reason="Gap baissier >= 3%"\n  elif close4<=opening*0.98: decision="SETUP INITIAL INVALIDE"; next_state="SURVEILLANCE CATALYSEUR"; reason="Baisse >= 2% apres 20 minutes"\n  elif red4>=3 and close4<opening: decision="SETUP INITIAL INVALIDE"; next_state="SURVEILLANCE CATALYSEUR"; reason="Au moins 3 bougies rouges sur 4"\n  else:\n   win=s.iloc[:12].copy(); typical=(win["High"]+win["Low"]+win["Close"])/3; win["VWAP"]=(typical*win["Volume"]).cumsum()/win["Volume"].cumsum().replace(0,float("nan"))\n   for idx,row in win.iloc[4:].iterrows():\n    op=float(row["Open"]); hi=float(row["High"]); lo=float(row["Low"]); cl=float(row["Close"]); vol=float(row["Volume"]); vw=float(row["VWAP"])\n    if lo<or_low or cl<=opening*0.98: decision="SETUP INITIAL INVALIDE"; next_state="SURVEILLANCE CATALYSEUR"; reason="Cassure baissiere Opening Range"; dt=str(idx); vwap_value=round(vw,4); break\n    if cl>or_high and cl>vw and vol>=vol4: decision="ACHAT CONFIRME"; next_state="POSITION A OUVRIR"; reason="Cassure haussiere + VWAP + volume"; dt=str(idx); vwap_value=round(vw,4); break\n   if decision=="EN ATTENTE" and len(s)>=12: decision="SETUP INITIAL INVALIDE"; next_state="SURVEILLANCE CATALYSEUR"; reason="Aucune confirmation pendant une heure"; row=win.iloc[-1]; dt=str(win.index[-1]); op=float(row["Open"]); hi=float(row["High"]); lo=float(row["Low"]); cl=float(row["Close"]); vol=float(row["Volume"]); vwap_value=round(float(row["VWAP"]),4)\n  decisions.append({"ticker":t,"signal_date":signal_date,"session_date":session,"decision_time":dt,"signal_price":round(signal_price,4),"opening_price":round(opening,4),"gap_pct":round(gap,2),"opening_range_high":round(or_high,4),"opening_range_low":round(or_low,4),"close_bougie_4":round(close4,4),"red_candles_4":red4,"initial_avg_volume":round(vol4),"decision_open":op,"decision_high":hi,"decision_low":lo,"decision_close":cl,"decision_volume":vol,""vwap":vwap_value,"decision":decision,"next_state":next_state,"reason":reason})\n  print("\\n"+t+" | Jour J "+session+" | "+decision)\n  print("Etat suivant : "+next_state+" | Motif : "+reason)\n  print("Opening "+str(round(opening,2))+" | OR Haut "+str(round(or_high,2))+" | OR Bas "+str(round(or_low,2))+" | Gap "+format(gap,"+.2f")+"%")\n  if dt: print("Bougie decision "+dt+" | O "+str(op)+" | H "+str(hi)+" | L "+str(lo)+" | C "+str(cl)+" | Volume "+str(vol)+" | VWAP "+str(vwap_value))\n except Exception as e: print("\\n"+t+" | ERREUR : "+str(e))\nf="intraday_decisions.csv"; fields=["ticker","signal_date","session_date","decision_time","signal_price","opening_price","gap_pct","opening_range_high","opening_range_low","close_bougie_4","red_candles_4","initial_avg_volume","decision_open","decision_high","decision_low","decision_close","decision_volume","vwap","decision","next_state","reason"]; old=[]\nif os.path.exists(f): old=list(csv.DictReader(open(f,encoding="utf-8")))\nrecords={(r["ticker"],r["signal_date"],r["session_date"]):r for r in old}\nfor r in decisions: records[(r["ticker"],r["signal_date"],r["session_date"])]=r\nwith open(f,"w",newline="",encoding="utf-8") as q:\n w=csv.DictWriter(q,fieldnames=fields,extrasaction="ignore"); w.writeheader(); w.writerows(records.values())\nprint("\\nJournal intraday sauvegarde :",f)')
